 "content": "def transform(grid):
    """Connect orthogonally aligned diamond-shaped groups of four 2s with 1s."""
    g = [row[:] for row in grid]
    h = len(g)
    w = len(g[0]) if h else 0
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (g[r - 1][c] == 2 and g[r + 1][c] == 2
                    and g[r][c - 1] == 2 and g[r][c + 1] == 2):
                centers.append((r, c))

    # For each diamond, connect only the nearest diamond in each cardinal
    # direction. The line begins beyond each diamond's facing 2-cell tip.
    for r, c in centers:
        for dr, dc in ((0, 1), (1, 0)):
            candidates = [
                (rr, cc) for rr, cc in centers
                if (rr - r, cc - c) == (0, cc - c) and dc == 1 and cc > c
                or (rr - r, cc - c) == (rr - r, 0) and dr == 1 and rr > r
            ]
            if not candidates:
                continue
            if dc == 1:
                rr, cc = min(candidates, key=lambda p: p[1])
                for x in range(c + 2, cc - 1):
                    g[r][x] = 1
            else:
                rr, cc = min(candidates, key=lambda p: p[0])
                for y in range(r + 2, rr - 1):
                    g[y][c] = 1
    return g


